    enonce: "<span dir=\"ltr\" class=\"expr pt\">ABC</span> مثلّث قائم الزاوية في <span dir=\"ltr\" class=\"expr pt\">A</span> حيث <span dir=\"ltr\" class=\"expr pt\">AB̂C = 46°.</span><br><span dir=\"ltr\" class=\"expr pt\">[BO)</span> و <span dir=\"ltr\" class=\"expr pt\">[CO)</span> منصّفا الزاويتين <span dir=\"ltr\" class=\"expr pt\">AB̂C</span> و <span dir=\"ltr\" class=\"expr pt\">AĈB</span>، و يتقاطعان في <span dir=\"ltr\" class=\"expr pt\">O.</span><br><svg class=\"figure\" direction=\"ltr\" viewBox=\"0 0 224 230\" width=\"224\" height=\"230\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"30.0\" y1=\"200.0\" x2=\"194.2\" y2=\"200.0\" stroke=\"#2c3e50\" stroke-width=\"1.6\"/><line x1=\"194.2\" y1=\"200.0\" x2=\"30.0\" y2=\"30.0\" stroke=\"#2c3e50\" stroke-width=\"1.6\"/><line x1=\"30.0\" y1=\"30.0\" x2=\"30.0\" y2=\"200.0\" stroke=\"#2c3e50\" stroke-width=\"1.6\"/><path d=\"M 52.0 200.0 A 22 22 0 0 0 30.0 178.0\" fill=\"none\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><text x=\"54.7\" y=\"179.3\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c0392b\">90°</text><path d=\"M 178.9 184.2 A 22 22 0 0 0 172.2 200.0\" fill=\"none\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><text x=\"161.9\" y=\"190.3\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c0392b\">46°</text><path d=\"M 30.0 52.0 A 22 22 0 0 0 45.3 45.8\" fill=\"none\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><circle cx=\"30.0\" cy=\"200.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"20.3\" y=\"214.1\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">A</text><circle cx=\"194.2\" cy=\"200.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"206.6\" y=\"210.4\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">B</text><circle cx=\"30.0\" cy=\"30.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"23.9\" y=\"21.4\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">C</text></svg><br>أحسب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">BÔC.</span>",
    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 46°</span>  و  <span dir=\"ltr\" class=\"expr pt\">[BO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AB̂C</span>  و  <span dir=\"ltr\" class=\"expr pt\">[CO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈB</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">BÔC.</span> نختار المنصّف لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: [BO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AB̂C</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 46°.</span> و لماذا لا الزاويتان المتقابلتان بالرأس ؟ لأنّها تحتاج زاويتين متقابلتين بالرأس، و لا وجود لهما هنا."},{"quoi":"القاعدة","math":"منصّف زاوية يقسمها إلى زاويتين متقايستين، قيس كلّ منهما نصف قيسها"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">[BO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AB̂C</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 46°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">CB̂O = 46° : 2 = 23°</span>"},{"quoi":"القاعدة","math":"مجموع قيسات زوايا مثلّث يساوي <span dir=\"ltr\" class=\"expr\">180°</span>"},{"quoi":"نطبّق","math":"في المثلّث <span dir=\"ltr\" class=\"expr pt\">ABC</span>  و  <span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 46°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AĈB = 180° - (90° + 46°) = 44°</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">[CO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈB</span>  و  <span dir=\"ltr\" class=\"expr pt\">AĈB = 44°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BĈO = 44° : 2 = 22°</span>"},{"quoi":"نطبّق","math":"في المثلّث <span dir=\"ltr\" class=\"expr pt\">OBC</span>  و  <span dir=\"ltr\" class=\"expr pt\">CB̂O = 23°</span>  و  <span dir=\"ltr\" class=\"expr pt\">BĈO = 22°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BÔC = 180° - (23° + 22°) = 135°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">BÔC = 135°</span>"}],
